package io.clipbridge.android;
import android.content.Context;
import org.json.*;
import java.util.*;
final class EngineRouter {
    private static final Map<String,Engine> engines=new HashMap<>();private static final Map<String,Long> failed=new HashMap<>();
    private static long created,eventClock;private static String text="",event="",last="";private static final Set<String> targets=new HashSet<>(),targetGroups=new HashSet<>(),doneGroups=new HashSet<>(),done=new HashSet<>(),busy=new HashSet<>();private static Context context;
    static void start(Context c){context=c;Thread worker=new Thread(()->{while(true){try{tick();}catch(Throwable ignored){}try{Thread.sleep(1000);}catch(InterruptedException e){return;}}},"ClipBridge-routes");worker.setDaemon(true);worker.start();}
    static synchronized void copy(String value){if(value.equals(last))return;last=value;text=value;created=System.currentTimeMillis()/1000;try{eventClock=context.getContentResolver().call(BridgeProvider.URI,"new-event",null,null).getLong("clock");}catch(Exception e){return;}event=UUID.randomUUID().toString().replace("-","");targets.clear();targets.addAll(engines.keySet());done.clear();doneGroups.clear();targetGroups.clear();try{JSONArray list=new JSONArray(context.getContentResolver().call(BridgeProvider.URI,"profiles",null,null).getString("profiles"));for(String pair:targets)targetGroups.add(group(list,pair));}catch(Exception ignored){}busy.clear();}
    static synchronized void received(String value){last=value;text="";event="";targets.clear();targetGroups.clear();done.clear();doneGroups.clear();busy.clear();}
    static synchronized long created(){return created;}
    static synchronized long clock(){return eventClock;}
    static synchronized String targetList()throws Exception{return new JSONObject().put("pairs",new JSONArray(targets)).put("groups",new JSONArray(targetGroups)).toString();}
    static synchronized void restore(String pair,String id,String value,long time,long clock,String selected){if(!event.isEmpty()||time+600<=System.currentTimeMillis()/1000)return;event=id;text=value;created=time;eventClock=clock;try{JSONArray list;if(selected.startsWith("{")){JSONObject saved=new JSONObject(selected);list=saved.getJSONArray("pairs");JSONArray groups=saved.optJSONArray("groups");if(groups!=null)for(int i=0;i<groups.length();i++)targetGroups.add(groups.getString(i));}else list=new JSONArray(selected);for(int i=0;i<list.length();i++)targets.add(list.getString(i));}catch(Exception e){targets.add(pair);}}
    static synchronized boolean owns(String pair,String id){return id.isEmpty() || event.equals(id)&&busy.contains(pair)&&!done.contains(pair);}
    static synchronized void success(String pair,String id){if(!event.equals(id))return;busy.remove(pair);done.add(pair);try{JSONArray profiles=new JSONArray(context.getContentResolver().call(BridgeProvider.URI,"profiles",null,null).getString("profiles"));String group=group(profiles,pair);doneGroups.add(group);for(int i=0;i<profiles.length();i++){JSONObject p=profiles.getJSONObject(i);String key=p.getJSONObject("config").getString("pair");if(group(profiles,key).equals(group))done.add(key);}}catch(Exception ignored){}}
    static synchronized void failure(String pair,String id){if(!event.equals(id))return;busy.remove(pair);failed.put(pair,System.currentTimeMillis()+30000);}
    private static String group(JSONArray list,String pair)throws Exception{for(int i=0;i<list.length();i++){JSONObject p=list.getJSONObject(i);if(p.getJSONObject("config").getString("pair").equals(pair))return !p.optString("groupKey").isEmpty()?"trusted:"+p.getString("groupKey"):p.optString("peerIdentity").length()==32?p.optString("peerIdentity"):pair;}return pair;}
    private static synchronized void tick()throws Exception{android.os.Bundle b=context.getContentResolver().call(BridgeProvider.URI,"profiles",null,null);context.getContentResolver().call(BridgeProvider.URI,"heartbeat",null,null);JSONArray profiles=new JSONArray(b.getString("profiles"));Set<String> active=new HashSet<>();for(int i=0;i<profiles.length();i++){JSONObject p=profiles.getJSONObject(i);String pair=p.getJSONObject("config").getString("pair");if(p.optBoolean("enabled",true)&&!b.getBoolean("paused")){active.add(pair);if(!engines.containsKey(pair)){Engine engine=new Engine(context,pair);engines.put(pair,engine);new android.os.Handler(android.os.Looper.getMainLooper()).post(()->{try{engine.start();}catch(Throwable ignored){engine.stop();}});}}}for(String pair:new ArrayList<>(engines.keySet()))if(!active.contains(pair)){engines.remove(pair).stop();busy.remove(pair);}
        if(b.getBoolean("paused")||active.isEmpty()){event="";text="";last="";targets.clear();targetGroups.clear();busy.clear();return;}for(String selected:new ArrayList<>(targetGroups)){boolean enabled=false;for(String route:active)if(group(profiles,route).equals(selected))enabled=true;if(!enabled)doneGroups.add(selected);}if(event.isEmpty())return;if(created+600<=System.currentTimeMillis()/1000){event="";targets.clear();busy.clear();return;}Set<String> seenGroups=new HashSet<>();for(int i=0;i<profiles.length();i++){JSONObject p=profiles.getJSONObject(i);String pair=p.getJSONObject("config").getString("pair"),group=group(profiles,pair);if(targets.contains(pair))targetGroups.add(group);if(!active.contains(pair)||!targets.contains(pair)&&!targetGroups.contains(group)||done.contains(pair)||doneGroups.contains(group)||seenGroups.contains(group))continue;boolean groupDone=false;for(String completed:done)if(group(profiles,completed).equals(group))groupDone=true;if(groupDone){done.add(pair);continue;}boolean groupBusy=false;for(String running:busy)if(group(profiles,running).equals(group))groupBusy=true;if(groupBusy){seenGroups.add(group);continue;}if(failed.getOrDefault(pair,0L)>System.currentTimeMillis())continue;Engine engine=engines.get(pair);if(engine!=null&&engine.ready()){busy.add(pair);seenGroups.add(group);engine.queue(text,event);}}
    }
}
